# Let me create a helper to analyze the transformations
def analyze_transformations(inputs, outputs):
    print("Analyzing transformations:")
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        print(f"Example {i+1}: '{inp}' → '{out}'")
        # Find differences
        min_len = min(len(inp), len(out))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_positions.append((j, inp[j], out[j]))

        # Check for longer replacements
        if len(inp) > len(out):
            # Some characters were removed
            print(f"  Characters removed at positions: {[j for j in range(len(out), len(inp))]}")
        elif len(out) > len(inp):
            # Some characters were added
            print(f"  Characters added at positions: {[j for j in range(len(inp), len(out))]}")

        if diff_positions:
            print(f"  Differences: {diff_positions}")
        else:
            print("  No character-by-character differences")

inputs = ['zwzuh', 'ubhe', 'vcvd', 'vu', 'xadbhf']
outputs = ['zwzifh', 'ifbhe', 'vcvd', 'vif', 'xadbhfw']
analyze_transformations(inputs, outputs)

